    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(receiver != address(0));
        amount = bound(amount, 1, 2 ** 250);
        // fund the contract so both reference (needs amount) and mutant (needs amount+1) succeed
        vm.deal(address(c), amount + 1);
        uint256 before = address(c).balance;
        c.sendTo(receiver, amount); // test contract is owner (deployer)
