pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        // admissible domain: owner-initiated send of a positive amount to a real address,
        // and the contract holds exactly the funds for this send
        vm.assume(receiver != address(0));
        vm.assume(amount > 0 && amount < type(uint256).max);
        vm.deal(address(c), amount);
        uint256 balBefore = address(c).balance;
        vm.prank(address(this)); // test contract is owner (deployer)
        bool ok;
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // Rule: a funded, admissible sendTo always succeeds and sends out EXACTLY
        // amount wei, draining the contract fully.
        assertTrue(ok && address(c).balance == balBefore - amount);
    }
}

