pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Reverter rev;

    function setUp() public {
        c = new C();
        rev = new Reverter();
    }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(this));
        amount = bound(amount, 1, type(uint256).max / 2);
        vm.deal(address(c), amount);
        bool ok;
        vm.prank(actor);
        try c.sendTo(address(rev), amount) {
            ok = true;
        } catch Error(string memory reason) {
            // reference: ownership require (no message) fires before any transfer,
            // so a non-owner call reverts with an EMPTY reason string.
            ok = bytes(reason).length == 0;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

