pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Reverter reverter;

    function setUp() public {
        c = new C();
        reverter = new Reverter();
    }

    function testFuzz_property(address actor, uint256 amount) public {
        // Admissible domain: caller must be a non-owner (owner is this test contract,
        // the deployer), and amount must be a positive sendable value.
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));
        amount = bound(amount, 1, type(uint96).max);
        vm.deal(address(c), amount);

        // Drive sendTo from a non-owner toward an adversarial receiver that bare-reverts.
        vm.prank(actor);
        (bool ok, bytes memory ret) = address(c).call(
            abi.encodeCall(C.sendTo, (address(reverter), amount))
        );

        // General rule: a non-owner call must be rejected by the ownership check
        // BEFORE any external interaction, so the revert is exactly the standard
        // empty Error(string) emitted by `require`.
        assertTrue(
            ok || keccak256(ret) == keccak256(abi.encodeWithSignature("Error(string)", "")),
            "non-owner must revert with the ownership require, not receiver bubble"
        );
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

