import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(this)); // exclude owner so the require must revert
        vm.assume(actor != address(0));
        amount = bound(amount, 1, address(this).balance == 0 ? 1e30 : 1e30);

        // receiver that accepts ETH so the transfer succeeds in the mutant
        Receiver r = new Receiver();

