        vm.deal(address(this), 1 wei);
        uint256 balBefore = address(c).balance;

        vm.prank(actor);
        try c.sendTo(address(r), amount) {
            // non-owner call should never succeed; if it did, balance moved
            assertTrue(address(c).balance == balBefore);
        } catch {
            // reference path: access control reverts before any transfer
            assertTrue(address(c).balance == balBefore);
        }
    }
}

