pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public { c = new C(); owner = msg.sender; }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != owner);
        amount = bound(amount, 1, type(uint256).max);

        // adversarial counterparty: passive observer that records receiving ETH
        Observer r = new Observer();
        vm.deal(address(c), amount);

        bool ok;
        vm.prank(actor);
        try c.sendTo(address(r), amount) { ok = true; } catch { ok = false; }

        // RULE: whenever sendTo reverts, the receiver must NOT have received
        // the transfer; only a fully successful call may move funds.
        assertTrue(!(r.gotEth() && !ok));
    }
}

contract Observer {
    bool public gotEth;
    receive() external payable { gotEth = true; }
}

