contract InvMutTest {

    C c;

    constructor(C _c) { c = _c; }

    function testSend(address receiver, uint amount) public {
        require(receiver != address(0));
        require(amount > 0);

        // authorized call to a normal receiver succeeds
        (bool okNormal, ) = address(c).call(
            abi.encodeWithSignature("sendTo(address,uint256)", receiver, amount)
        );
        require(okNormal);

        // the same authorized call to the zero address must revert
        (bool okZero, ) = address(c).call(
            abi.encodeWithSignature("sendTo(address,uint256)", address(0), amount)
        );

        assert(okZero == false);
    }
}

